phase1.code:
fn main() {
    // ---- Dangling references are prevented by the compiler ----

    // ---- Invalid: returning reference to local variable ----
    // let r = dangle();  // ERROR!

    // ---- Valid: returning ownership instead ----
    let s = no_dangle();
    println!("s: {}", s);

    // ---- Invalid: mutable reference to local ----
    // let r2 = dangle_mut();  // ERROR!

    // ---- Valid: mutable reference with proper lifetime ----
    let mut s2 = String::from("hello");
    let r3 = &mut s2;
    r3.push_str(" world");
    println!("s2: {}", s2);

    // ---- Valid: reference to data that outlives the reference ----
    let s3 = String::from("hello");
    let r4 = &s3;
    println!("r4: {}", r4);
    // s3 outlives r4, so this is safe

    // ---- Invalid: reference outlives data ----
    // let r5;
    // {
    //     let s4 = String::from("hello");
    //     r5 = &s4;  // ERROR! s4 doesn't live long enough
    // }
    // println!("r5: {}", r5);

    // ---- Valid: data outlives reference ----
    let s5 = String::from("hello");
    let r6;
    {
        r6 = &s5;  // s5 lives longer than the inner scope
    }
    println!("r6: {}", r6);
}

// fn dangle() -> &String {
//     let s = String::from("hello");
//     &s  // ERROR! s is dropped here
